from pathlib import Path
import html,json,shutil
R=Path(__file__).resolve().parents[1];D=R.parent/(R.name+'-pages')
theory=json.loads((R/'docs/theory.json').read_text())
sections=[
('Introducció',theory['introduccio'],[],[]),
('Què és Git',theory['git'],[],[]),
('Què és Git Flow',theory['gitflow'],[],[]),
('Per què utilitzem Git Flow',theory['motius'],[],[]),
('Creació del repositori','Repositori públic creat amb GitHub CLI, autenticat com LucaMZM. Git, gh, Node.js i npm disponibles. HTML5 Boilerplate v9.0.1 descarregat des del repositori oficial, amb llicència conservada.',[1,2,3],['github/01-repositori.png']),
('Creació de main i develop','main naix amb el commit 5a3c16a. develop es crea abans de desenvolupar la interfície. La simulació dels tres usuaris es limita als missatges de commit; no es falsifiquen identitats.',[5,6,7,12],[]),
('Desenvolupament inicial','Home implementat en develop amb HTML5 Boilerplate adaptat, cabecera visual, navegació, presentació, objectius i footer. Commit 3c786f4. L enunciat original es localitza durant el procés i es contrasta el seu esquema general.',[8,10],['aplicacion/03-home.png']),
('Feature de contingut HTML','Branca creada des de develop abans de programar. textContent insereix text literal i innerHTML interpreta només una plantilla fixa de confiança. Commit 3fd18e5. No s interpreta cap entrada lliure de l usuari com a HTML.',[11,13,15,16,18],['aplicacion/05-contingut.png']),
('Feature d atributs HTML','setAttribute actualitza title, getAttribute en llig el valor i disabled alterna una propietat booleana. Commit 22bf601. La fusió conserva un commit amb dos pares.',[19,20,22,23,25],['aplicacion/08-atributs.png']),
('Feature d estils CSS','Color i fontSize es modifiquen amb style; classList alterna el ressaltat. El botó de restabliment recupera l estat inicial i aria-pressed reflecteix l estat. Commit 5238368.',[26,27,29,30,32],['aplicacion/11-estils.png']),
('Fusió de les funcionalitats','Les tres features s integren amb --no-ff: 70ce7aa, d4b7b6f i 8201996. Les branques es mantenen publicades perquè el professor puga inspeccionar-les.',[18,25,32,54],[]),
('Release v1.0','release/v1.0 prepara package.json i el favicon local. Integració en main (3c277c4) i develop (6d9b2ba), etiqueta anotada v1.0 i GitHub Release publicada. La preparació s ha identificat com usuari1; l enunciat original assignava aquesta fase a usuari3. Es conserva el registre real sense reescriure autoria ni historial.',[33,34,36,39,40,42,58],['github/16-release-v1.png']),
('Hotfix','hotfix/milloresV_1_0 es crea des de main. La millora real incorpora Restableix contingut i comptador Unicode. Commit 51485c8. Fusió doble en main (d0c5a2c) i develop (80e5ffb), etiqueta v1.0.1; es conserva v1.0.',[44,45,47,48,50,51,53,59],['aplicacion/18-hotfix.png']),
('GitHub Project','Project creat des de GitHub web després de descartar l ampliació del permís project de la CLI. Les huit issues s importen des del repositori. Estats Todo, In Progress i Done. Cada issue inclou responsable simulat, descripció, branca i, quan existeix, commit. Project: https://github.com/users/LucaMZM/projects/1.',[],['github/21-project-proces.png']),
('Accés del professor al projecte','enminqui2 apareix en Manage access amb rol Read. La captura mostra dos membres. Accés de lectura concedit mitjançant Invite; la interfície no mostra una acceptació separada, per tant no s afirma que s haja acceptat. No s ha ampliat l accés al repositori.',[],['github/22-acces-professor.png']),
('Captures del procés','Les imatges són captures reals de navegador. Les operacions de terminal es mostren com a eixida registrada autèntica, no com a captures de terminal. Cada registre inclou data UTC, ordre exacta, codi de retorn, estat Git i HEAD. Els registres anteriors a la primera confirmació mostren correctament que HEAD encara no existeix. El canvi de branca del registre 068 va fallar per un registre modificat; es va recuperar amb worktrees, tal com mostra 073.',[54,68,71,72,73],[]),
('Resultat de l’aplicació','15 comprovacions locals aprovades: contingut literal segur, HTML fix, lectura i escriptura d atributs, disabled, color, mida, classe, restabliment i hotfix. Sense errors JavaScript ni de consola; sense desbordament horitzontal a 390, 768 i 1280 px. L informe JSON conserva també la primera resposta 404 de Pages abans de publicar-la. La verificació final qa-final.json aprova les 15 proves sobre la URL pública i tots els enllaços; audit.json aprova 30 comprovacions de Git Flow.',[],['aplicacion/03-home.png']),
('Conclusions i enllaços',theory['conclusions']+' Documentació publicada des de l arrel de gh-pages. L aplicació es copia en app/ per conservar la memòria com a portada. PDF i DOCX es generen des del mateix document i s inclouen en entrega/.', [71,78,83],[])
]
sections[-1]=(sections[-1][0], 'El desenvolupament ha completat les tres funcionalitats del DOM, la release v1.0 i el hotfix v1.0.1 amb fusions verificables. Les 15 proves funcionals i les 30 comprovacions de Git Flow han passat. El Project recull les huit tasques i enminqui2 té accés Read, amb acceptació no confirmada. La preparació de la release va utilitzar el paper simulat usuari1, diferència declarada respecte al PDF. La documentació i els documents de lliurament conserven resultats i evidències autèntics.', sections[-1][2], sections[-1][3])
if (R/'evidencias/pages/verification.json').exists():
 v=json.loads((R/'evidencias/pages/verification.json').read_text());sections[-1]=(sections[-1][0],sections[-1][1]+' Repositori, documentació i aplicació: HTTP 200 segons la verificació final registrada.',sections[-1][2],['pages/25-documentacio.png'] if (R/'evidencias/pages/25-documentacio.png').exists() else [])
D.mkdir(exist_ok=True)
for f in ['index.html','style.css','boilerplate.css','app.js','favicon.svg','LICENSE-H5BP.txt']:
 (D/'app').mkdir(exist_ok=True);shutil.copy2(R/f,D/'app'/f)
shutil.copytree(R/'evidencias',D/'evidencias',dirs_exist_ok=True)
if (R/'entrega').exists():shutil.copytree(R/'entrega',D/'entrega',dirs_exist_ok=True)
