def polish(t):
 for a,b in [('d octubre',"d’octubre"),('l’aplicació',"l’aplicació"),('L aplicació',"L’aplicació"),('d atributs',"d’atributs"),('d estils',"d’estils"),('l estat',"l’estat"),('l usuari',"l’usuari"),('L enunciat',"L’enunciat"),('l enunciat',"l’enunciat"),('s interpreta',"s’interpreta"),('s integren',"s’integren"),('s ha',"s’ha"),('s afirma',"s’afirma"),('s haja',"s’haja"),('l accés',"l’accés"),('d acceptació',"d’acceptació"),('l arrel',"l’arrel"),('s inclouen',"s’inclouen"),('cabecera','capçalera')]: t=t.replace(a,b)
 return t
esc=html.escape
nav=''.join(f'<a href="#s{i}">{i}. {esc(polish(t))}</a>' for i,(t,_,_,__) in enumerate(sections,1))
body=''
for i,(title,txt,logs,imgs) in enumerate(sections,1):
 body+=f'<section id="s{i}"><h2>{i}. {esc(polish(title))}</h2><p>{esc(polish(txt))}</p>'
 for image in imgs:
  body+=f'<figure><a href="evidencias/{image}"><img src="evidencias/{image}" alt="Captura real: {esc(polish(title))}" loading="lazy"></a><figcaption>Captura de navegador real. {esc(polish(title))}.</figcaption></figure>'
 for n in logs:
  paths=list((R/'evidencias/terminal').glob(f'{n:03d}-*.txt'))
  if paths:
   p=paths[0];body+=f'<details><summary>Ordre i eixida registrada {p.stem}</summary><p>Registre autèntic; no és una captura de terminal.</p><pre>{esc(p.read_text())}</pre><a href="evidencias/terminal/{p.name}">Obri el registre complet</a></details>'
 body+='</section>'
body+='<section><h2>Publicació GitHub Pages i lliurament</h2><p>Documentació servida des de gh-pages i / (root).</p><figure><img src="evidencias/pages/24-configuracio.png" alt="Configuració real de GitHub Pages"><figcaption>Publicació real des de la branca gh-pages.</figcaption></figure><p><a href="app/">Obri l’aplicació interactiva</a> · <a href="https://github.com/LucaMZM/javascript-dom-gitflow">Repositori públic</a> · <a href="https://github.com/users/LucaMZM/projects/1">GitHub Project</a></p><p><a href="entrega/Practica1_GitFlow_LucaMZM.pdf">Descarrega la memòria PDF</a> · <a href="entrega/Practica1_GitFlow_LucaMZM.docx">Descarrega el DOCX editable</a></p><h3>Fonts i recursos</h3><p><a href="https://git-scm.com/book/en/v2">Pro Git</a> · <a href="https://github.com/h5bp/html5-boilerplate/tree/v9.0.1">HTML5 Boilerplate v9.0.1</a></p></section>'
body+='<section><h2>Estat final del Project</h2><p>Les huit tasques estan en Done; Todo i In Progress estan buits. Es conserva també la captura intermèdia del procés.</p><figure><img src="evidencias/github/21-project-final.png" alt="Tauler final amb huit tasques completades"><figcaption>Estat final real del Project.</figcaption></figure><h2>Registre cronològic complet</h2><p>Les ordres executades es poden auditar amb els seus resultats, incloses incidències i recuperacions.</p><ul>'
for p in sorted((R/'evidencias/terminal').glob('*.txt')):body+=f'<li><a href="evidencias/terminal/{p.name}">{p.stem}</a></li>'
body+='</ul></section>'
style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f9fd;color:#1d304a;font:17px/1.7 "Avenir Next","Segoe UI",sans-serif}header{background:#173b69;color:white;padding:3rem max(5vw,1rem)}h1{font-size:clamp(2rem,4vw,3.4rem);line-height:1.2;max-width:25ch}header a{color:white}header p{max-width:75ch}.layout{display:grid;grid-template-columns:280px minmax(0,850px);max-width:1250px;margin:auto;gap:3rem;padding:3rem 1.5rem}nav{position:sticky;top:1rem;max-height:95vh;overflow:auto;align-self:start;font-size:.88rem}nav a{display:block;padding:.35rem;color:#173b69}section{margin:0 0 4rem;scroll-margin:1rem}h2{font-size:1.7rem;line-height:1.3}a{color:#174d8c}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#e8edf5;padding:1rem;font:13px/1.6 Menlo,monospace}details{margin:1rem 0;border-bottom:1px solid #c5d2e3;padding:.8rem 0}summary{cursor:pointer;font-weight:650}img{width:100%;height:auto;border:1px solid #c5d2e3}figure{margin:2rem 0}figcaption{font-size:.85rem}a:focus-visible,summary:focus-visible{outline:3px solid #a95400;outline-offset:3px}.skip{background:white;padding:.5rem;color:#173b69}footer{padding:2rem;text-align:center}@media(max-width:850px){.layout{display:block;padding:1.3rem}nav{position:static;max-height:none;margin-bottom:2rem}h2{font-size:1.5rem}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
(D/'docs.css').write_text(style)
(D/'index.html').write_text(f'<!doctype html><html lang="ca-valencia"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Memòria completa de la pràctica Git Flow de Luca Mazmishvili amb evidències reals."><title>Pràctica 1 · Git Flow · LucaMZM</title><link rel="stylesheet" href="docs.css"><link rel="icon" href="app/favicon.svg"></head><body><header><a class="skip" href="#memoria">Ves a la memòria</a><h1>Pràctica 1<br>Sistemes de control de versions</h1><p>Luca Mazmishvili · LucaMZM · 26 d’octubre de 2026</p><p>Memòria del desenvolupament d’un laboratori JavaScript DOM amb Git Flow, evidències autèntiques i publicació en GitHub.</p><a href="app/">Obri el laboratori JavaScript</a></header><div class="layout"><nav aria-label="Índex de la memòria">{nav}</nav><main id="memoria">{body}</main></div><footer>Professor revisor: enminqui2 · Pràctica acadèmica</footer></body></html>')
